<template>
	<view class="container">
		<u-loading-page :loading="true" v-if="load" fontSize="28rpx" />
		<block v-else>
		<view class="top">
			<view class="left">
				<view class="store-name">{{store_name}}</view>
				<view class="store-desc">付款给商家</view>
			</view>
			<image :src="getFullUrl(store_logo)" mode="aspectFit" class="top-img"/>
		</view>
		<scroll-view scroll-y="true" class="scroll">
			<view class="info">
				<view class="info-top" @click="goNext">
					<text class="tit">选择商品</text>
					<view class="right">
						<text class="gongji">共{{sumCount}}件</text>
						<text class="heji">合计</text>
						<text class="amount">￥{{sumPrice}}</text>
						<u-icon name="arrow-right" bold color="#ACACAC" size="16"/>
					</view>
				</view>
				<view class="cart-item" v-if="lists.length>0">
					<view class="cart-goods-items">
						<view class="goods-item" v-for="(item,childIndex) in lists" :key="childIndex">
							<image :src="item.full_image" class="goods-img" mode="aspectFit"/>
							<view class="goods-item-right">
								<view class="goods-name">{{item.goods_name}}</view>
								<view class="goods-spec">市场价:{{item.market_price}}</view>
								<view class="goods-right">
									<view class="goods-price">
										<text>¥</text>
										<text class="jiage">{{item.goods_price}}</text>
									</view>
									<view class="goods-num-box">
										<text @click="changeNum(item,-1,childIndex)">-</text>
										<text class="number">{{item.sel_num}}</text>
										<text :class="{'dis':item.sel_num>=item.store_count}"
											@click="changeNum(item,1,childIndex)">+</text>
									</view>
								</view>
							</view>
						</view>
					</view>
				</view>
				<view class="verify">
					<text class="text">登录密码</text>
					<view class="row-input">
						<u-input
						    placeholder="请输入登录密码"
							border="none"
							type="text"
							password
							placeholderClass="placeholder28"
							v-model="password"
						    clearable />
					</view>
				</view>
				<view class="title">支付方式</view>
				<view class="pay-items">
					<view class="pay-item" @click="changePay(0)">
						<image src="@/static/order/yue.png" mode="widthFix" class="zf-img"/>
						<text>{{money_text}}</text>
						<image :src="type==0?'/static/common/checkbox_select.png':'/static/common/checkbox_unselect.png'" mode="widthFix" class="check-img"/>
					</view>
					<view class="pay-item" @click="changePay(1)">
						<image src="@/static/order/weixin.png" mode="widthFix" class="zf-img"/>
						<text>微信</text>
						<image :src="type==1?'/static/common/checkbox_select.png':'/static/common/checkbox_unselect.png'" mode="widthFix" class="check-img"/>
					</view>
				</view>
				<view class="submit">
					<button class="submit-btn" @click="submit" :disabled="submitDisabled || btnDisabled">确认付款</button>
				</view>
			</view>
		</scroll-view>
		</block>
	</view>
</template>

<script>
	var _this;
	export default {
		data() {
			return {
				store_id:0,
				submitDisabled:false,
				money_text:'',
				store_type_tv:'',
				store_name:'',
				store_logo:'',
				password:'',
				type:0,
			}
		},
		onLoad(e) {
			_this = this;
			if(e.store_id){
				_this.store_id = e.store_id
			}else{
				this.$u.toast('提交参数有误',()=>{
					_this.finish()
				})
				return
			}
			uni.$on('selectGoods',res=>{
				_this.lists = res.list
			})
			_this.get_dp_fukuan()
		},
		onUnload() {
			uni.$off('selectGoods')
		},
		methods: {
			goNext(){
				_this.toNext(`/pages/index/store-goods-detail?store_id=${_this.store_id}`)
			},
			changeNum(item,step,index) {
				var number = item.sel_num + step
				if (step < 0) {
					item.sel_num = number
					if(number<=0){
						_this.lists.splice(index,1)
					}
				} else {
					if (number > item.store_count) {
						return;
					}
					item.sel_num = number
				}
			},
			changePay(type){
				if(_this.type == type){
					return
				}
				_this.type = type
			},
			submit(){
				_this.get_dp_fukuan(1)
			},
			getSelectList(){
				let select = []
				for (var i = 0; i < _this.lists.length; i++) {
					let item = _this.lists[i]
					let temp = {}
					temp.goods_id = item.goods_id
					temp.goods_num = item.sel_num
					select.push(temp)
				}
				return select;
			},
			async get_dp_fukuan(is_post=0){
				const params = {
					store_id: _this.store_id,
					is_post: is_post,
				}
				if (is_post==1) {
					if (_this.password=='') {
						uni.$u.toast('请输入登录密码')
						return;
					}
					let openid=uni.getStorageSync('openid');
					params.type = _this.type
					params.openid = openid
					params.is_xcx = 2
					params.password = _this.password
					params.list = JSON.stringify(_this.getSelectList())
					_this.submitDisabled = true
					setTimeout(()=>{
						_this.submitDisabled = false
					},2000)
				}
				const data = await _this.$post('port/dp_fukuan', params)
				if(data.code==1){
					_this.$u.toast(data.msg,()=>{
						_this.toNext('/pages/order/order-list',true)
					})
				}else if(data.code==-50){
					uni.requestPayment({
						provider: 'wxpay',
						timeStamp: data.data.timeStamp+'',
						nonceStr: data.data.nonceStr,
						package: data.data.package,
						signType: data.data.signType,
						paySign: data.data.sign,
						success(res) {
							console.log('success:' + JSON.stringify(res));
							_this.$u.toast('支付成功',()=>{
								_this.toNext('/pages/order/order-list',true)
							})
						},
						fail(err) {
							console.log('fail:' + JSON.stringify(err));
						}
					});
				}else if(data.code==-100){
					this.$u.toast(data.msg)
					_this.submitDisabled = true
				}else if(data.code==-10){
					_this.money_text = data.money_text
					_this.store_type_tv = data.store_type_tv
					_this.store_name = data.store_name
					_this.store_logo = data.store_logo
				}else if(data.code==-1){
					this.$u.toast(data.msg,()=>{
						_this.finish()
					})
				}else{
					this.$u.toast(data.msg)
				}
				if (_this.load) {
					_this.load = false
				}
			}
		},
		computed:{
			sumCount:{
				cache:false,
				get() {
					return this.lists.length
				}
			},
			sumPrice:{
				cache:false,
				get() {
					if (this.lists.length<=0) {
						return '0.00'
					}
					let total = 0
					for (var i = 0; i < this.lists.length; i++) {
						let item = this.lists[i]
						total+= item.goods_price * item.sel_num
					}
					return total.toFixed(2)
				}
			},
			btnDisabled:{
				cache:false,
				get() {
					if (this.lists.length<=0) {
						return true
					}
					return false
				}
			}
		}
	}
</script>

